#include <iomanip>
#include <iostream>

double siguiente_consecutivo(float base) {
    // La suma actual se calcula como float.
    float resultado = base + 1.0f;
    return resultado;
}

int main() {
    int caso = 0;
    if (!(std::cin >> caso)) {
        return 1;
    }

    float base = 0.0f;
    switch (caso) {
    case 1:
        base = 16777216.0f;
        break;
    case 2:
        base = 33554432.0f;
        break;
    case 3:
        base = -33554432.0f;
        break;
    case 4:
        base = 0.0f;
        break;
    case 5:
        base = 16777215.0f;
        break;
    default:
        return 1;
    }

    const double nuevo = siguiente_consecutivo(base);
    const double cambio = nuevo - static_cast<double>(base);
    std::cout << std::fixed << std::setprecision(0);
    std::cout << "Anterior=" << base << '\n';
    std::cout << "Nuevo=" << nuevo << '\n';
    std::cout << "Cambio=" << cambio << '\n';
    return 0;
}

