#include <iostream>
#include <limits>

int main() {
    float paso = std::numeric_limits<float>::epsilon();
    float uno = 1.0f;
    float dos = 2.0f;

    float sobre_uno = uno + paso;
    float medio_salto = dos + paso;
    float salto_completo = dos + 2.0f * paso;

    std::cout << (sobre_uno > uno) << ':'
              << (medio_salto == dos) << ':'
              << (salto_completo > dos);
    return 0;
}

